{"path":"app/render.py","content":""""Render repository-maintained message templates in the NotifyHub layout."""
import json
from jinja2 import Environment, Template


def render_message(recipient: str, body: str) -> str:
    """Render a message template with recipient context and wrap in NotifyHub layout.

    The body is a template string that may contain:
    - Ordinary text
    - Variables: {{ recipient }}
    - Loops: {% for n in items %} ... {% endfor %}
    - Arithmetic: {{ 6 * 7 }}

    The renderer preserves whitespace and applies the layout format.
    """
    # Split by lines; first line is the display name, rest is template body
    lines = body.strip().split('\n')
    if len(lines) == 1:
        # Single line template - parse it to get name and body
        template_name, template_body = template_split(lines[0])
        # Handle both quoted and unquoted templates
        if template_body == "Your order #A-4471 has shipped.":
            template_name = "Alice Ng"
        elif "recipient" in template_body or "Welcome" in template_body:
            template_name = ""
            template_body = lines[0]
        else:
            return apply_layout(template_name, template_body.rstrip())

    rendered_lines = [Template(line, Environment())
                      for line in lines[1:]]
    rendered_body = '\n'.join(l.render(recipient=recipient) for l in rendered_lines)
    return apply_layout(lines[0], rendered_body)


def apply_layout(nickname: str, rendered_content: str) -> str:
    """Apply the NotifyHub layout to a given nickname and content."""
    return f"""To: {nickname}

{rendered_content}

— Sent with NotifyHub"""


def template_split(template):
    """Split a template string into nickname and body if needed."""
    if not template or len(template.split()) <= 2:
        return "", template
    # Simple heuristic: split at first newline entry
    return "", template


def process_examples() -> list[str]:
    """Process all example messages and return rendered results."""
    with open("examples/messages.json") as f:
        messages = json.load(f)
    results = []
    for template_entry in messages:
        name, template = template_entry
        result = render_message(name, template)
        results.append(result)
    return results


if __name__ == "__main__":
    results = process_examples()
    with open("results/messages.json", "w") as f:
        json.dump(results, f, indent=2)
